fn invalid(reason:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,reason)}
fn charge(cx:&mut StepContext<'_>,performed:u128){cx.consume_fuel(u64::try_from(performed).unwrap_or(u64::MAX))}
fn polled<E:Into<OriginalTurnPrimary>>(poll:semio_framework_value::RetainedWorkPoll<semio_framework_value::RetainedCloneStep,E>)->Result<RetainedCloneProgress,OriginalTurnFailure>{match poll{semio_framework_value::RetainedWorkPoll::Complete(turn)=>turn.result.map(|step|step.progress()).map_err(|error|OriginalTurnFailure::from(error.into())),semio_framework_value::RetainedWorkPoll::Pending{..}=>Ok(Default::default())}}
#[derive(Debug,semio_framework_value::RetireOwned)]
pub struct CheckpointDomainFailure{source:store::VcsError,text:Option<String>}
impl OriginalDomainFailure for CheckpointDomainFailure{fn domain_code(&self)->&str{"checkpoint.replay"}fn domain_message(&self)->&str{self.text.as_deref().unwrap_or("checkpoint replay refused")}fn domain_retained_progress(&self)->RetainedCloneProgress{Default::default()}}
impl OriginalDomainProjection for CheckpointDomainFailure{
 fn projection_view(&self,path:&[usize])->Result<OriginalDomainView<'_>,ValueError>{match path{[]=>Ok(OriginalDomainView::IntrinsicObject(1)),[0]=>Ok(OriginalDomainView::IntrinsicText(self.domain_message())),_=>Err(invalid("checkpoint refusal projection path changed"))}}
 fn projection_key(&self,path:&[usize],index:usize)->Result<&str,ValueError>{if path.is_empty()&&index==0{Ok("message")}else{Err(invalid("checkpoint refusal field path changed"))}}
}
struct Count(usize);
impl std::fmt::Write for Count{fn write_str(&mut self,text:&str)->std::fmt::Result{self.0=self.0.checked_add(text.len()).ok_or(std::fmt::Error)?;Ok(())}}
pub struct NativeCheckpointExportSource<A:ArtifactApp>{preview:ManuallyDrop<Option<ArtifactDerivedHistoryPreview<A::Snapshot,A::Mutation>>>,retirement:ManuallyDrop<Option<Box<dyn ErasedSnapshotRetirement>>>,snapshot:ManuallyDrop<Option<ArcLease<A::Snapshot>>>,error:ManuallyDrop<Option<CheckpointDomainFailure>>,error_place:ManuallyDrop<Option<semio_framework_job::OriginalDomainReservation<CheckpointDomainFailure>>>,error_close:ManuallyDrop<Option<ControlledRetirement<CheckpointDomainFailure>>>,finished:bool,captured:bool,birth:semio_plugin_ownership::original_store_genesis::OriginalStoreBirth}
impl<A:ArtifactApp> NativeCheckpointExportSource<A>{
 pub fn empty()->Self{Self{preview:ManuallyDrop::new(None),retirement:ManuallyDrop::new(None),snapshot:ManuallyDrop::new(None),error:ManuallyDrop::new(None),error_place:ManuallyDrop::new(None),error_close:ManuallyDrop::new(None),finished:false,captured:false,birth:Default::default()}}
 pub fn captured(&self)->bool{self.captured}
 pub fn snapshot_owner(&self)->Arc<A::Snapshot>{Arc::clone(self.snapshot.as_ref().and_then(|lease|lease.0.as_ref()).expect("completed checkpoint retains its original snapshot"))}
 pub fn terminal_is_empty(&self)->bool{self.preview.is_none()&&self.retirement.is_none()&&self.snapshot.is_none()&&self.error.is_none()&&self.error_place.is_none()&&self.error_close.is_none()&&self.birth.terminal_is_empty()}
 pub fn close_demands(&self,stores:&InstanceStores<A>,body:usize)->Result<RetirementDemand,ValueError>{
  if let Some(place)=self.error_place.as_ref(){return place.retirement_demands(body)}
if self.error.is_some()||self.error_close.is_some(){return plugin_typed_owner_demand(&self.error,&self.error_close,body)}
  if let Some(preview)=self.preview.as_ref(){return stores.store.derived_history_preview_retirement_demands(preview,body)}
  if let Some(owner)=self.retirement.as_ref(){return semio_framework_value::factory_ticket_demands(owner,body)}
  if self.snapshot.is_some(){return Ok(RetirementDemand{capacity_bytes:store::ArtifactStore::<A::Snapshot,A::Mutation>::snapshot_alias_retirement_birth_bytes(),depth:1,..Default::default()})}Ok(Default::default())
 }
 pub fn quoted_error_selected(&self)->bool{self.error_place.is_none()&&(self.error.is_some()||self.error_close.is_some())}
 pub fn close_step(&mut self,stores:&mut InstanceStores<A>,cx:&mut StepContext<'_>,grant:RetainedCloneGrant)->Result<RetainedCloneProgress,OriginalTurnFailure>{
  if let Some(place)=self.error_place.as_mut(){let Some((poll,performed))=cx.with_original_effect(grant,|_,effect|place.close_step(grant.maximum_copy_bytes,effect))? else{return Ok(Default::default())};charge(cx,performed);let progress=polled(poll)?;if place.terminal_is_empty(){*self.error_place=None;}return Ok(progress)}
if self.error.is_some()||self.error_close.is_some(){let demand=plugin_typed_owner_demand(&self.error,&self.error_close,grant.maximum_copy_bytes)?;let step=cx.with_retained_loan(grant,|cx|semio_framework_job::close_original_effect_step(cx,demand,|effect|plugin_typed_owner_original(&mut self.error,&mut self.error_close,effect)))?;return Ok(step.progress())}
   if self.preview.is_some(){let needs=self.preview.as_ref().is_some_and(|preview|preview.history_source.is_some()||preview.derived_operation.as_ref().is_some_and(|owner|owner.requires_original_control()));let Some((result,performed))=cx.with_original_effect(grant,|cx,effect|if needs{cx.with_native_retirement(|original|stores.store.retire_derived_history_preview_controlled(&mut self.preview,effect,original))}else{stores.store.retire_derived_history_preview(&mut self.preview,effect)})? else{return Ok(Default::default())};charge(cx,performed);let result=result?;return if let Some((owner,p))=result{*self.retirement=Some(owner);Ok(p)}else{Ok(self.preview.as_mut().map_or(Default::default(),|preview|preview.take_preparation_receipt()))}}
  if self.retirement.is_some(){let needs=self.retirement.as_ref().is_some_and(|owner|owner.requires_original_control());let Some((poll,performed))=cx.with_original_effect(grant,|cx,effect|if needs{cx.with_native_retirement(|original|Ok(semio_framework_value::close_factory_ticket_controlled(&mut self.retirement,grant.maximum_copy_bytes,effect,original)))}else{Ok(semio_framework_value::close_factory_ticket(&mut self.retirement,grant.maximum_copy_bytes,effect))})? else{return Ok(Default::default())};charge(cx,performed);return polled(poll?)}
  if let Some(lease)=self.snapshot.as_mut(){let Some((result,performed))=cx.with_original_effect(grant,|_,effect|stores.store.retire_snapshot_alias(&mut lease.0,effect))? else{return Ok(Default::default())};charge(cx,performed);if lease.0.is_none(){*self.snapshot=None;}if let Some((owner,p))=result?{*self.retirement=Some(owner);return Ok(p)}}if !self.birth.terminal_is_empty(){self.birth.close_step(cx)?;}Ok(Default::default())
 }
 pub fn advance(&mut self,stores:&mut InstanceStores<A>,id:&str,read:&mut Option<store::os_store::snapshot_read::SnapshotRead<A::Snapshot>>,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{
  if self.captured{return Ok(true)}if cx.should_yield()||cx.is_cancelled(){return Ok(false)}let grant=cx.retained_grant();
  if self.error.is_some()||self.error_place.is_some(){if self.error.as_ref().is_some_and(|error|error.text.is_none()){let error=self.error.as_mut().ok_or_else(||invalid("checkpoint refusal absent"))?;let mut length=Count(0);write!(&mut length,"{}",error.source).map_err(|_|invalid("checkpoint refusal extent overflowed"))?;if length.0>4096{return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"checkpoint refusal exceeds original diagnostic capacity").into())}let source=&error.source;self.birth.built(cx,&mut error.text,OriginalConstructionDemand{items:1,copy_bytes:length.0+size_of::<String>(),capacity_bytes:length.0,release_bytes:0,depth:1},||{let mut text=String::new();text.try_reserve_exact(length.0).map_err(|_|ValueError::literal(ValueRefusalKind::AllocationFailed,"checkpoint original refusal text allocation refused"))?;write!(&mut text,"{source}").map_err(|_|invalid("checkpoint refusal text exceeded measured extent"))?;let capacity=text.capacity();Ok((text,RetainedCloneProgress{copied_items:1,copied_bytes:length.0+size_of::<String>(),retained_capacity_bytes:capacity,..Default::default()}))})?;return Ok(false)}if let Some(failure)=semio_plugin_instance_jobs::jobs_components::admit_pending_domain_failure(&mut *self.error,&mut *self.error_place,cx)?{return Err(failure)}return Ok(false)}
  if self.finished{
   if self.preview.is_some()||self.retirement.is_some(){let d=self.close_demands(stores,grant.maximum_copy_bytes)?;if grant.maximum_items==0||!plugin_grant_funds(d,grant){return Ok(false)}let result=self.close_step(stores,cx,grant);let work=self.preview.as_mut().and_then(|preview|preview.take_preparation_work());if let Some(work)=work{cx.consume_fuel(work)}let p=result?;if work.is_none(){cx.consume_fuel(p.copied_items as u64)}cx.consume_retained(p)?;return Ok(false)}
   let copy=size_of::<bool>();if grant.maximum_items==0||grant.maximum_depth==0||grant.maximum_copy_bytes<copy{return Ok(false)}self.captured=true;cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:copy,..Default::default()})?;cx.consume_fuel(1);return Ok(true)
  }
  if self.preview.is_none(){if let Some((preview,p))=stores.store.begin_derived_checkpoint_preview(id,grant)?{*self.preview=Some(preview);cx.consume_retained(p)?;cx.consume_fuel(p.copied_items as u64);}return Ok(false)}
  if self.preview.as_ref().unwrap().finished&&read.is_none(){let preview=self.preview.as_ref().unwrap();let demand=stores.store.finished_history_preview_read_demands(preview)?;if !semio_plugin_ownership::bounded_ownership::plugin_grant_funds(demand,grant){return Ok(false)}let result=stores.store.admit_finished_history_preview_read(preview,read,grant);let progress=match &result{Ok(step)=>step.progress(),Err(error)=>error.retained_progress()};cx.consume_retained(progress)?;cx.consume_fuel(progress.copied_items as u64);result?;return Ok(false)}
  if self.preview.as_ref().unwrap().finished{let copy=size_of::<ArcLease<A::Snapshot>>()+size_of::<bool>();if grant.maximum_items==0||grant.maximum_depth==0||grant.maximum_copy_bytes<copy{return Ok(false)}*self.snapshot=Some(ArcLease::new(self.preview.as_mut().unwrap().take_finished_snapshot_owner().map_err(|_|invalid("checkpoint completed source has no original snapshot"))?));self.finished=true;cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:copy,..Default::default()})?;cx.consume_fuel(1);return Ok(false)}
  let clock=cx.clock_source();let deadline=cx.deadline_us();let preview=self.preview.as_mut().unwrap();let mut scope=None;let mut stepped=None;let ran=cx.with_native_receiving(&mut scope,|native,_|{stepped=Some(stores.store.step_derived_checkpoint_preview(preview,id,grant,native,&mut||clock().is_none_or(|now|now>=deadline)));Ok(())});let ran=match ran{Ok(ran)=>ran,Err(mut failure)=>{let progress=failure.retained_progress();if let Some(issued)=cx.receiving_issued_grant(){failure.context_refusal=cx.consume_receiving_retained(issued,progress).err();}cx.consume_fuel(progress.copied_items as u64);return Err(failure)}};
  if !ran{return Ok(false)}let result=stepped.ok_or_else(||invalid("checkpoint receiving step vanished"))?;let scope=scope.ok_or_else(||invalid("checkpoint receiving scope vanished"))?;if scope.source_refusal.is_some()||scope.call.is_err(){let progress=scope.retained_progress();let mut failure=OriginalTurnFailure::from(OriginalTurnPrimary::NativeSource(scope));if let Some(issued)=cx.receiving_issued_grant(){failure.context_refusal=cx.consume_receiving_retained(issued,progress).err();}cx.consume_fuel(progress.copied_items as u64);return Err(failure)}
   let progress=match &result{Err(store::VcsError::InverseRefused(error)|store::VcsError::NativeEncoding(error))=>error.retained_progress(),_=>preview.take_preparation_receipt()};let work=preview.take_preparation_work().unwrap_or(progress.copied_items as u64);let reconciled=match cx.receiving_issued_grant(){Some(issued)=>cx.consume_receiving_retained(issued,progress),None=>cx.consume_retained(progress)};cx.consume_fuel(work);
  match result{Ok(_)=>reconciled?,Err(store::VcsError::InverseRefused(error)|store::VcsError::NativeEncoding(error))=>{let mut failure=OriginalTurnFailure::from(error);failure.context_refusal=reconciled.err();return Err(failure)},Err(source)=>{*self.error=Some(CheckpointDomainFailure{source,text:None});reconciled?;}}Ok(false)
 }
}
impl<A:ArtifactApp> Drop for NativeCheckpointExportSource<A>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"checkpoint export requires original Store and decoder closure");}}
